//! Bounded, caller-configured work accounting and cancellation.
//!
//! Charges count completed work and are intentionally not rolled back when a
//! caller later rolls back a higher-level source transaction. Callers should
//! charge/checkpoint in batches of at most 256 work units.

use std::sync::atomic::{AtomicBool, Ordering};

/// Categories shared by incremental parsers, renderers, and related workers.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(usize)]
pub enum WorkKind {
    SourceRead,
    TokenVisit,
    ReferenceProbe,
    Transform,
    Expansion,
    Edge,
    PaintVisit,
    ClipChain,
    ClipChild,
    ClipEdge,
    ShapePixel,
    ShapeSample,
    FillEdgeTest,
    FillIntervalTest,
    StrokeTest,
    ScanlineEdgeEntry,
    ShapeRowVisit,
    BoundaryMark,
    FilterPixel,
    AnimationTransform,
    Media,
}

impl WorkKind {
    pub const ALL: [Self; 21] = [
        Self::SourceRead, Self::TokenVisit, Self::ReferenceProbe, Self::Transform,
        Self::Expansion, Self::Edge, Self::PaintVisit, Self::ClipChain, Self::ClipChild,
        Self::ClipEdge, Self::ShapePixel, Self::ShapeSample, Self::FillEdgeTest,
        Self::FillIntervalTest, Self::StrokeTest, Self::ScanlineEdgeEntry,
        Self::ShapeRowVisit, Self::BoundaryMark, Self::FilterPixel,
        Self::AnimationTransform, Self::Media,
    ];

    const fn index(self) -> usize { self as usize }
}

/// The first reason a work-control job stopped.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stop { Canceled, Limit, Overflow }

/// Error returned by a controlled operation, preserving its original error.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlledError<E> {
    Original(E),
    Canceled,
    Limit,
    Overflow,
    OutOfMemory,
}

impl<E> From<Stop> for ControlledError<E> {
    fn from(stop: Stop) -> Self {
        match stop {
            Stop::Canceled => Self::Canceled,
            Stop::Limit => Self::Limit,
            Stop::Overflow => Self::Overflow,
        }
    }
}

/// A real result shape for work performed by a controlled worker.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ControlledStep<T, E> {
    Pending { charged_units: u64 },
    Complete(T),
    Failed(ControlledError<E>),
}

/// Object-safe boundary for bounded work and cancellation checks.
pub trait WorkControl {
    fn charge(&mut self, kind: WorkKind, units: u64) -> Result<(), Stop>;
    fn checkpoint(&mut self) -> Result<(), Stop>;
}

/// Fixed-size per-kind caps. Unconfigured kinds default to `u64::MAX`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WorkLimits([u64; WorkKind::ALL.len()]);

impl WorkLimits {
    /// Create a policy with no per-kind cap below the `u64` counter maximum.
    pub const fn unlimited() -> Self { Self([u64::MAX; WorkKind::ALL.len()]) }

    /// Set one kind's cap, returning the updated fixed-size policy.
    pub const fn with_limit(mut self, kind: WorkKind, limit: u64) -> Self {
        self.0[kind.index()] = limit;
        self
    }

    const fn get(self, kind: WorkKind) -> u64 { self.0[kind.index()] }
}

impl Default for WorkLimits {
    fn default() -> Self { Self::unlimited() }
}

/// Immutable snapshot of successfully accepted work units.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WorkStats {
    total_units: u64,
    per_kind: [u64; WorkKind::ALL.len()],
}

impl WorkStats {
    pub const fn total_units(&self) -> u64 { self.total_units }
    pub const fn units(&self, kind: WorkKind) -> u64 { self.per_kind[kind.index()] }
}

/// Safe budget and cancellation state borrowing the caller's real cancel flag.

use vexel_base::Span;
use vexel_geometry::Point;
use vexel_scene::{Diagnostic, ErrorKind, KernelResources, LimitKind, Rect, Result, SceneView, Selection, ShapeId, ShapeInput, WorkControl};

fn invalid(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset,
    }
}

fn mapping(view: SceneView<'_>) -> Option<(f64, f64, f64, f64)> {
    let v = view.viewport;
    if v.width == 0
        || v.height == 0
        || ![v.view_x, v.view_y, v.view_width, v.view_height]
            .into_iter()
            .all(f64::is_finite)
        || v.view_width <= 0.0
        || v.view_height <= 0.0
    {
        return None;
    }
    let (mut sx, mut sy) = (
        f64::from(v.width) / v.view_width,
        f64::from(v.height) / v.view_height,
    );
    let (mut ox, mut oy) = (0.0, 0.0);
    let mut a = v.aspect;
    if !a.set {
        a.align_x = 0.5;
        a.align_y = 0.5;
    }
    if !a.none {
        let s = if a.slice { sx.max(sy) } else { sx.min(sy) };
        sx = s;
        sy = s;
        ox = (f64::from(v.width) - v.view_width * s) * a.align_x;
        oy = (f64::from(v.height) - v.view_height * s) * a.align_y;
    }
    [sx, sy, ox, oy]
        .into_iter()
        .all(f64::is_finite)
        .then_some((sx, sy, ox, oy))
}

fn bounds(view: SceneView<'_>, id: ShapeId) -> Option<Selection> {
    let shape = view.shape(id)?;
    let edges = shape.edges.slice(view.edges)?;
    let (min_x, min_y, max_x, max_y) = if let Some(first) = edges.first() {
        let mut b = (first.a.x, first.a.y, first.a.x, first.a.y);
        for edge in edges {
            for p in [edge.a, edge.b] {
                if !p.x.is_finite() || !p.y.is_finite() {
                    return None;
                }
                b.0 = b.0.min(p.x);
                b.1 = b.1.min(p.y);
                b.2 = b.2.max(p.x);
                b.3 = b.3.max(p.y);
            }
        }
        b
    } else {
        (0.0, 0.0, 0.0, 0.0)
    };
    let (sx, sy, ox, oy) = mapping(view)?;
    let left = ox + (min_x - view.viewport.view_x) * sx;
    let top = oy + (min_y - view.viewport.view_y) * sy;
    let right = ox + (max_x - view.viewport.view_x) * sx;
    let bottom = oy + (max_y - view.viewport.view_y) * sy;
    if ![left, top, right, bottom].into_iter().all(f64::is_finite) {
        return None;
    }
    Some(Selection {
        shape: id,
        source: shape.source.element,
        user_bounds: Rect {
            x: min_x,
            y: min_y,
            width: max_x - min_x,
            height: max_y - min_y,
        },
        device_bounds: Rect {
            x: left,
            y: top,
            width: right - left,
            height: bottom - top,
        },
        transform: shape.source.transform,
    })
}

/// Safe equivalent of `svg_shape_bounds_query`; stale IDs and malformed ranges return None.
pub fn bounds_query(view: SceneView<'_>, shape: ShapeId) -> Option<Selection> {
    bounds(view, shape)
}

fn segment_distance(p: Point, a: Point, b: Point) -> f64 {
    let dx = b.x - a.x;
    let dy = b.y - a.y;
    let l = dx * dx + dy * dy;
    if l == 0.0 {
        return (p.x - a.x).hypot(p.y - a.y);
    }
    let t = (((p.x - a.x) * dx + (p.y - a.y) * dy) / l).clamp(0.0, 1.0);
    (p.x - (a.x + t * dx)).hypot(p.y - (a.y + t * dy))
}

fn fill_contains(view: SceneView<'_>, id: ShapeId, x: f64, y: f64) -> bool {
    let Some(shape) = view.shape(id) else {
        return false;
    };
    let Some(edges) = shape.edges.slice(view.edges) else {
        return false;
    };
    let mut winding = 0i32;
    let mut parity = false;
    let visible = shape.image.is_some()
        || edges.iter().enumerate().any(|(i, _)| {
            view.edge_colors
                .get(shape.edges.first + i)
                .is_some_and(|c| c[3] != 0)
        });
    for edge in edges {
        let up = edge.a.y <= y && edge.b.y > y;
        let down = edge.b.y <= y && edge.a.y > y;
        if !up && !down {
            continue;
        }
        let crossing = edge.a.x + (y - edge.a.y) * (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
        if crossing > x {
            winding += if up { 1 } else { -1 };
            parity = !parity;
        }
    }
    visible && shape.filled && if shape.evenodd { parity } else { winding != 0 }
}

fn stroke_contains(view: SceneView<'_>, id: ShapeId, p: Point, tolerance: f64) -> bool {
    let Some(shape) = view.shape(id) else {
        return false;
    };
    if shape.stroke.rgba[3] == 0 || shape.stroke.width <= 0.0 {
        return false;
    }
    let inv = shape.stroke_inverse;
    let Some(local) = vexel_geometry::affine_map_point(inv, p) else {
        return false;
    };
    let norm = (inv.a * inv.a + inv.b * inv.b + inv.c * inv.c + inv.d * inv.d).sqrt();
    let radius = shape.stroke.width * 0.5 + tolerance * norm;
    let Some(subpaths) = shape.subpaths.slice(view.path_subpaths) else {
        return false;
    };
    let Some(edges) = shape.edges.slice(view.edges) else {
        return false;
    };
    if !subpaths.is_empty() {
        for path in subpaths {
            let Some(end) = path.first_edge.checked_add(path.edge_count) else {
                return false;
            };
            let Some(path_edges) = view.edges.get(path.first_edge..end) else {
                return false;
            };
            let n = path_edges.len().saturating_sub(usize::from(!path.closed));
            for edge in &path_edges[..n] {
                let (Some(a), Some(b)) = (
                    vexel_geometry::affine_map_point(inv, edge.a),
                    vexel_geometry::affine_map_point(inv, edge.b),
                ) else {
                    return false;
                };
                if segment_distance(local, a, b) <= radius {
                    return true;
                }
            }
        }
        return false;
    }
    let n = edges
        .len()
        .saturating_sub(usize::from(!shape.stroke_closed));
    edges[..n].iter().any(|e| {
        match (
            vexel_geometry::affine_map_point(inv, e.a),
            vexel_geometry::affine_map_point(inv, e.b),
        ) {
            (Some(a), Some(b)) => segment_distance(local, a, b) <= radius,
            _ => false,
        }
    })
}

/// Reverse painter-order selection with the concrete clip provider and caller work control.
pub fn hit_test(
    view: SceneView<'_>,
    x: f64,
    y: f64,
    tolerance: f64,
    resources: &dyn KernelResources,
    control: &mut dyn WorkControl,
) -> Result<Option<Selection>> {
    if ![x, y, tolerance].into_iter().all(f64::is_finite)
        || tolerance < 0.0
        || tolerance > 1_000_000.0
    {
        return Err(invalid(0));
    }
    for i in (0..view.shapes.len()).rev() {
        control.checkpoint().map_err(|s| Diagnostic {
            kind: match s {
                vexel_base::Stop::Canceled => ErrorKind::Canceled,
                vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
                vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
            },
            offset: 0,
        })?;
        if view.shapes.get(i).is_none() {
            continue;
        }
        let Some(id) = view.shape_id(i) else {
            continue;
        };
        let shape = view.shape(id).ok_or_else(|| invalid(0))?;
        if let Some(clip) = shape.clip {
            if !resources.clip_contains(view, clip, x, y, control)? {
                continue;
            }
        }
        if !fill_contains(view, id, x, y) && !stroke_contains(view, id, Point { x, y }, tolerance) {
            continue;
        }
        return Ok(bounds(view, id));
    }
    Ok(None)
}

/// Returns the narrowest source range; ties select the later painter-order shape.
pub fn element_at_offset(view: SceneView<'_>, offset: usize) -> Option<Selection> {
    view.shapes
        .iter()
        .enumerate()
        .filter_map(|(i, s)| {
            let span = s.source.element;
            (span.start <= offset && offset < span.end && span.start < span.end)
                .then_some((i, span))
        })
        .min_by(|(ia, a), (ib, b)| {
            a.end
                .saturating_sub(a.start)
                .cmp(&b.end.saturating_sub(b.start))
                .then_with(|| ib.cmp(ia))
        })
        .and_then(|(i, _)| view.shape_id(i).and_then(|id| bounds(view, id)))
}

/// Assigns a source span before `append_shape`; published scene spans stay immutable.
pub fn source_assign(input: &mut ShapeInput, source: &[u8], span: Span) -> Result<()> {
    if span.slice(source).is_none() {
        return Err(invalid(span.start));
    }
    input.shape.source.element = span;
    Ok(())
}

