//! Explicit safe allocation accounting over caller-owned buffers.
use vexel_scene::{
    AllocationLease, AllocationTag, ChargeLedger, Diagnostic, ErrorKind, LimitKind, Result,
};

fn arithmetic() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Arithmetic),
        offset: 0,
    }
}
fn invalid() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset: 0,
    }
}

#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
pub struct MemoryStats {
    pub source_bytes: usize,
    pub peak_live_bytes: usize,
    pub live_bytes: usize,
    pub total_allocated_bytes: usize,
    pub allocation_count: usize,
    pub token_array_bytes: usize,
    pub reference_index_bytes: usize,
    pub clip_copy_bytes: usize,
    pub output_bytes: usize,
    pub overflow: bool,
}

/// Per-job tracker. Every charge is attached to an opaque shared ledger lease.
#[derive(Debug, Default)]
pub struct AllocationTracking {
    leases: Vec<(AllocationTag, AllocationLease, usize)>,
    stats: MemoryStats,
}

impl AllocationTracking {
    pub fn tracking_start(job: &ChargeLedger) -> Self {
        Self {
            leases: Vec::new(),
            stats: MemoryStats {
                source_bytes: job.stats().source_bytes,
                ..MemoryStats::default()
            },
        }
    }
    pub fn track_capacity<T>(
        &mut self,
        job: &mut ChargeLedger,
        tag: AllocationTag,
        values: &Vec<T>,
    ) -> Result<()> {
        let bytes = values
            .capacity()
            .checked_mul(std::mem::size_of::<T>())
            .ok_or_else(arithmetic)?;
        let next_live = self
            .stats
            .live_bytes
            .checked_add(bytes)
            .ok_or_else(arithmetic)?;
        let next_total = self
            .stats
            .total_allocated_bytes
            .checked_add(bytes)
            .ok_or_else(arithmetic)?;
        let next_count = self
            .stats
            .allocation_count
            .checked_add(usize::from(bytes != 0))
            .ok_or_else(arithmetic)?;
        let next_tag = match tag {
            AllocationTag::TokenArray => Some(
                self.stats
                    .token_array_bytes
                    .checked_add(bytes)
                    .ok_or_else(arithmetic)?,
            ),
            AllocationTag::ReferenceIndex => Some(
                self.stats
                    .reference_index_bytes
                    .checked_add(bytes)
                    .ok_or_else(arithmetic)?,
            ),
            AllocationTag::ClipCopy => Some(
                self.stats
                    .clip_copy_bytes
                    .checked_add(bytes)
                    .ok_or_else(arithmetic)?,
            ),
            AllocationTag::Output => Some(
                self.stats
                    .output_bytes
                    .checked_add(bytes)
                    .ok_or_else(arithmetic)?,
            ),
            AllocationTag::None => None,
        };
        self.leases.try_reserve(1).map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
        let lease = job.admit(tag, bytes)?;
        self.stats.live_bytes = next_live;
        self.stats.total_allocated_bytes = next_total;
        self.stats.allocation_count = next_count;
        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(next_live);
        match tag {
            AllocationTag::TokenArray => self.stats.token_array_bytes = next_tag.unwrap(),
            AllocationTag::ReferenceIndex => self.stats.reference_index_bytes = next_tag.unwrap(),
            AllocationTag::ClipCopy => self.stats.clip_copy_bytes = next_tag.unwrap(),
            AllocationTag::Output => self.stats.output_bytes = next_tag.unwrap(),
            AllocationTag::None => {}
        }
        self.leases.push((tag, lease, bytes));
        Ok(())
    }
    pub fn release_last(&mut self, job: &mut ChargeLedger) -> Result<()> {
        let (_, lease, bytes) = *self.leases.last().ok_or_else(invalid)?;
        let live = self
            .stats
            .live_bytes
            .checked_sub(bytes)
            .ok_or_else(arithmetic)?;
        job.release(lease)?;
        self.leases.pop();
        self.stats.live_bytes = live;
        Ok(())
    }
    pub fn tracking_stop(&self, job: &ChargeLedger) -> MemoryStats {
        let ledger = job.stats();
        MemoryStats {
            source_bytes: ledger.source_bytes,
            peak_live_bytes: ledger.peak_live_bytes,
            live_bytes: ledger.live_bytes,
            total_allocated_bytes: ledger.total_allocated_bytes,
            allocation_count: ledger.allocation_count,
            token_array_bytes: ledger.token_array_bytes,
            reference_index_bytes: ledger.reference_index_bytes,
            clip_copy_bytes: ledger.clip_copy_bytes,
            output_bytes: ledger.output_bytes,
            overflow: ledger.overflow,
        }
    }
}

/// Reserve into a fresh buffer, charge its actual capacity while the old buffer remains
/// live, then transfer values and publish. Before calling, the caller must have an active
/// ledger lease for current Vec capacity; release that old lease after return, when the old
/// allocation is dropped. `None` means the existing charged capacity already suffices.
pub fn reserve_table<T>(
    job: &mut ChargeLedger,
    tag: AllocationTag,
    table: &mut Vec<T>,
    additional: usize,
) -> Result<Option<AllocationLease>> {
    let required = table.len().checked_add(additional).ok_or_else(arithmetic)?;
    required
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)?;
    if required <= table.capacity() {
        return Ok(None);
    }
    let mut replacement = Vec::new();
    replacement
        .try_reserve_exact(required)
        .map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
    let actual = replacement
        .capacity()
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)?;
    let lease = job.admit(tag, actual)?;
    replacement.append(table);
    std::mem::swap(table, &mut replacement);
    Ok(Some(lease))
}

use std::sync::Arc;
use vexel_scene::{AllocationTag, ChargeLedger};
use vexel_scene_query::{AllocationTracking, reserve_table};

fn ledger() -> ChargeLedger {
    let source = Arc::new(b"source".to_vec());
    ChargeLedger::new(&source, 1 << 20, 32).unwrap()
}

#[test]
fn explicit_capacity_is_charged_and_released() {
    let mut job = ledger();
    let mut tracking = AllocationTracking::tracking_start(&job);
    let baseline = job.stats().live_bytes;
    let mut values = Vec::<u32>::new();
    values.try_reserve_exact(8).unwrap();
    tracking
        .track_capacity(&mut job, AllocationTag::TokenArray, &values)
        .unwrap();
    let stats = tracking.tracking_stop(&job);
    assert!(stats.token_array_bytes >= 8 * std::mem::size_of::<u32>());
    assert!(stats.live_bytes >= stats.token_array_bytes + stats.source_bytes);
    assert!(stats.source_bytes > 0);
    let before_release = job.stats().live_bytes;
    tracking.release_last(&mut job).unwrap();
    assert_eq!(
        job.stats().live_bytes,
        before_release - stats.token_array_bytes
    );
    assert!(job.stats().live_bytes > baseline); // retained lease registry capacity is charged
}

#[test]
fn reserve_table_charges_replacement_before_publishing() {
    let mut job = ledger();
    let mut values = vec![3u32, 5];
    let old_bytes = values.capacity() * std::mem::size_of::<u32>();
    let old_lease = job.admit_vec(AllocationTag::Output, &values).unwrap();
    let lease = reserve_table(&mut job, AllocationTag::Output, &mut values, 64)
        .unwrap()
        .unwrap();
    assert_eq!(&values[..2], &[3, 5]);
    assert!(values.capacity() >= 66);
    let new_bytes = values.capacity() * std::mem::size_of::<u32>();
    assert_eq!(job.stats().output_bytes, old_bytes + new_bytes);
    job.release(old_lease).unwrap();
    assert_eq!(job.stats().output_bytes, new_bytes);
    job.release(lease).unwrap();
    assert_eq!(job.stats().output_bytes, 0);
}

#[test]
fn reserve_table_rejects_budget_without_losing_values() {
    let mut values = vec![11u8];
    let source = Arc::new(Vec::new());
    let old_bytes = values.capacity() * std::mem::size_of::<u8>();
    let mut job = ChargeLedger::new(&source, old_bytes + 512, 4).unwrap();
    let old = job.admit_vec(AllocationTag::Output, &values).unwrap();
    assert!(reserve_table(&mut job, AllocationTag::Output, &mut values, 1024).is_err());
    assert_eq!(values, vec![11]);
    job.release(old).unwrap();
}

#[test]
fn reserve_table_reports_size_arithmetic_before_reserving() {
    let mut job = ledger();
    let mut values = Vec::<u64>::new();
    let error =
        reserve_table(&mut job, AllocationTag::Output, &mut values, usize::MAX).unwrap_err();
    assert_eq!(
        error.kind,
        vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic)
    );
    assert!(values.is_empty());
}

